	ld (xiy), de
	ld xde, xwa
	ld (xwa), hl
	ld (xsp + 16), xbc
	ld xwa, (xsp + 12)
	ld (xwa), xbc
	cpw (xiy), 0x1
	jrl nz, ParaLoadOpt_ReturnZero
	ld wa, (xde)
	cp wa, 0x8
	jrl z, LABEL_F772FE
	cps wa, 7
	jr z, LABEL_F772D3
	ld xbc, (xsp + 8)
	cps wa, 3
	jr z, LABEL_F772AB
	cps wa, 2
	jrl nz, ParaLoadOpt_ReturnZero
	ld a, (xiz)
	extz wa
	sla wa, 2
	ld_sril3 XWA, 0x07, 0xE4, 0xE0
	push xwa
	ld xwa, (xsp + 20)
	push xwa
	.include "tonegen_voice_ctrl.s"
	call SendEvent
	ld xde, (xsp + 30)
	set 7, de
	ld xwa, 0xFFFFFFFF
	ld xbc, 0x1C00009
	call SendEvent
	ld xde, (xsp + 30)
	ld xwa, (xsp + 38)
	ld xbc, 0x1C00034
	call SendEvent

; Builds an SSF presentation workspace and sends event 0x1C0001C via direct
; SendEvent (FA9660).  This is the CRITICAL path that allows
; AcPresentationControlProc to pass its 0xB80A type-tag check and start
; SSF playback.
;
; The workspace (at XSP+14) is populated byte-by-byte from XSP+30/31:
;   workspace[0] = byte at (XSP+31)   -- must be 0x0A for tag 0x0000B80A
;   workspace[1] = byte at (XSP+30)   -- must be 0xB8
;   workspace[2..3] = shifted/zero bytes
;
; Reached via event 0x1C00038 (direct) or event 0x1C00030 (via
; GroupBoxProc_Ev1C00030 fall-through).
GroupBoxProc_StartSSFPresentation:
	ld xwa, (xsp + 38)
	call SetRootObject
	ld xwa, 0x1C0001C
	call SetRootEvent
	lda xwa, (xsp + 18)
	call SetRootParam
	lda xbc, (xsp + 30)
	ld xde, xbc
	inc 1, xde
	lda xwa, (xsp + 14)
	ld c, (xbc)
	ld (xwa + 3), c
	ld_spib C, 0xE8
	ld (xwa + 2), c
	ld_spib C, 0xE8
	ld (xwa + 1), c
	ld c, (xde)
	ld (xwa), c
	lda xbc, (xsp + 10)
	lda xde, (xsp + 8)
	call SndParam_ResolveWidget
	cp hl, 0xFFFF
	jrl z, GroupBox_ReturnZero

; Loop body: iterates over SSF items via FCD437, builds workspace fields,
; and sends event 0x1C0001C for each item via direct SendEvent.
; Loops until FCD4FF reports no more items (HL == 0xFFFF).
GroupBoxProc_SSFItemLoop:
	ld xwa, (xsp + 10)
	ld (xsp + 18), xwa
	ld xwa, (xsp + 10)
	call SndParam_LookupReadOnly
	lda xde, (xsp + 18)
	ld (xde + 4), hl
	ldw (xde + 6), 0x0
	lds32 xwa, 0
	ld (xde + 8), xwa
	ld xwa, 0xFFFFFFFF
	ld xbc, 0x1C0001C
	call SendEvent
	lda xwa, (xsp + 14)
	lda xbc, (xsp + 10)
	lda xde, (xsp + 8)
	call SndParam_ResolveWidget
	cp hl, 0xFFFF
	jr nz, GroupBoxProc_SSFItemLoop
	jrl GroupBox_ReturnZero

	; --- Event 0x1E0006E: Cancel/Back handler ---
	; Iterates the 17-entry widget structure array at 0x0274E8
	; (28-byte entries: stride = (ix*8 - ix)*4 = ix*28).
	; If event param (XWA) is nonzero: activates entries and sends 0x1C00026.
	; If event param is zero: deactivates entries and sends 0x1C00026.
	; Each entry has: byte[0]=active, byte[1]=enabled, dword[2]=workspace,
	; dword[6]=event(0x1C00007), dword[10]=focus_id, offset[14]=secondary.
GroupBox_CancelBack:
	lds iz, 0

GroupBox_CancelBack_Loop:
	ld ix, iz
	extz xix
	lda_24 xiy, 0x0274e8
	ld xde, xix
	sll xde, 3
	sub xde, xix
	sll xde, 2
	ld xbc, xiy
	add xbc, xde
	ld xwa, (xsp + 30)
	or xwa, xwa
	jrl z, GroupBox_CancelBack_Deactivate
	ld (xsp + 4), xix
	ld xhl, xbc
	ld xwa, (xsp + 38)
	ld (xbc + 2), xwa
	ld xwa, 0x1C00007
	ld (xbc + 6), xwa
	ld (xbc + 10), xix
	lda xwa, (xde + 14)
	add xiy, xwa
	ld xwa, (xsp + 38)
	ld (xiy + 2), xwa
	ld xwa, 0x1C00007
	ld (xiy + 6), xwa
	ld wa, iz
	add wa, 0x80
	extz xwa
	ld (xiy + 10), xwa
	cp (xbc), 0x0
	jr z, GroupBox_CancelBack_ActivateSecondary
	lda xwa, (xhl + 1)
	cp (xwa), 0x0
	jr nz, GroupBox_CancelBack_ActivateSecondary
	ld (xwa), 0x1
	ld xwa, 0x1C00026
	push xwa
	ld xwa, (xsp + 8)
	push xwa
	ld xwa, 0x10
	ld xbc, (xsp + 46)
	ld xde, (xsp + 46)
	call SetApTimer

GroupBox_CancelBack_ActivateSecondary:
	ld bc, iz
	extz xbc
	ld xwa, xbc
	sll xwa, 3
	sub xwa, xbc
	sll xwa, 2
	lda xbc, (xwa + 14)
	ld xwa, 0x274E8
	add xwa, xbc
	cp (xwa), 0x0
	jrl z, GroupBox_CancelBack_LoopNext
	inc 1, xwa
	cp (xwa), 0x0
	jrl nz, GroupBox_CancelBack_LoopNext
	ld (xwa), 0x1
	ld xwa, 0x1C00026
	push xwa
	ld wa, iz
	add wa, 0x80
	extz xwa
	push xwa
	ld xwa, 0x10
	ld xbc, (xsp + 46)
	ld xde, (xsp + 46)
	call SetApTimer
	jr GroupBox_CancelBack_LoopNext

GroupBox_CancelBack_Deactivate:
	ld xwa, xbc
	cp (xbc), 0x0
	jr z, GroupBox_CancelBack_DeactivateSecondary
	inc 1, xwa
	cp (xwa), 0x0
	jr z, GroupBox_CancelBack_DeactivateSecondary
	ld (xwa), 0x0
	ld xwa, 0x1C00026
	push xwa
	push xix
	ld xwa, 0x10
	ld xbc, (xsp + 46)
	ld xde, (xsp + 46)
	call KillApTimer

GroupBox_CancelBack_DeactivateSecondary:
	ld bc, iz
	extz xbc
	ld xwa, xbc
	sll xwa, 3
	sub xwa, xbc
	sll xwa, 2
	lda xbc, (xwa + 14)
	ld xwa, 0x274E8
	add xwa, xbc
	cp (xwa), 0x0
	jr z, GroupBox_CancelBack_LoopNext
	inc 1, xwa
	cp (xwa), 0x0
	jr z, GroupBox_CancelBack_LoopNext
	ld (xwa), 0x0
	ld xwa, 0x1C00026
	push xwa
	ld wa, iz
	add wa, 0x80
	extz xwa
	push xwa
	ld xwa, 0x10
	ld xbc, (xsp + 46)
	ld xde, (xsp + 46)
	call KillApTimer

GroupBox_CancelBack_LoopNext:
	inc 1, iz
	cp iz, 0x10
	jrl ule, GroupBox_CancelBack_Loop
	jrl GroupBox_ReturnZero

	; --- Event 0x1E0006F: Dial Enable ---
	; Stores WA (from XBC param) into dial enable register at 0x03EF50.
GroupBox_DialEnable:
	ld wa, bc
	calr SetDialEnable
	jrl GroupBox_ReturnZero

	; --- Event 0x1E00070: Dial Down ---
	; Registers down-direction parameters (workspace, event 0x1C00007, param)
	; into dial state at 0x03EF56/5E/66 and updates dial focus.
GroupBox_DialDown:
	ld xde, (xsp + 30)
	ld xwa, (xsp + 38)
	ld xbc, 0x1C00007
	calr SetDialDown
	jrl GroupBox_ReturnZero

	; --- Event 0x1E00071: Dial Up ---
	; Registers up-direction parameters (workspace, event 0x1C00007, param)
	; into dial state at 0x03EF52/5A/62 and updates dial focus.
GroupBox_DialUp:
	ld xde, (xsp + 30)
	ld xwa, (xsp + 38)
	ld xbc, 0x1C00007
	calr SetDialUp
	jrl GroupBox_ReturnZero

	; --- Event 0x1E00088: Get Dial Focus ---
	; Returns current dial focus value from 0x03EF6A in XHL.
GroupBox_GetDialFocus:
	calr GetDialFocus
	jrl GroupBox_Epilogue

	; --- Event 0x1E00087: Set Dial Focus ---
	; Stores dial focus (XWA) at 0x03EF6A and broadcasts 0x1C0002C.
GroupBox_SetDialFocus:
	calr SetDialFocus
	jrl GroupBox_ReturnZero

	; --- Events 0x1E00079/0x1E00078: UP/DOWN Navigation ---
	; Calls 0xFA5867 (lookup), then dispatches 0x1E000B4 via FA9660.
	; Falls through to loop that broadcasts 0x1C00009 (close/hide) to
	; all active entries in the 0x0274E8 structure array.
GroupBox_NavUpDown:
	call GetTitleNow
	ld xwa, xhl
	ld xde, (xsp + 30)
	ld xbc, (xsp + 34)
	jr GroupBox_NavDispatch
	call UIRender_RetStub1
	jrl GroupBox_ReturnZero
	call UIRender_RetStub2
	jrl GroupBox_ReturnZero
	lds wa, 0
	calr SetDialEnable
	ld xwa, 0xFFFFFFFF
	st32_24 0x03ef6a, xwa
	call InitializeTimer
	ld xwa, (xsp + 38)
	ld xbc, 0x1E000B4
	lds32 xde, 0

GroupBox_NavDispatch:
	call SendEvent
	jr GroupBox_ReturnZero
	lds iz, 0

GroupBox_CloseAll_Loop:
	ld de, iz
	extz xde
	ld xwa, xde
	sll xwa, 3
	sub xwa, xde
	sll xwa, 2
	ld xbc, 0x274E8
	add xbc, xwa
	cp (xbc), 0x0
	jr z, GroupBox_CloseAll_Secondary
	ld xwa, 0xFFFFFFFF
	ld xbc, 0x1C00009
	call SendEvent

GroupBox_CloseAll_Secondary:
	ld wa, iz
	extz xwa
	ld xbc, xwa
	sll xbc, 3
	sub xbc, xwa
	sll xbc, 2
	lda xwa, (xbc + 14)
	ld xbc, 0x274E8
	add xbc, xwa
	cp (xbc), 0x0
	jr z, GroupBox_CloseAll_Next
	ld de, iz
	add de, 0x80
	extz xde
	ld xwa, 0xFFFFFFFF
	ld xbc, 0x1C00009
	call SendEvent

GroupBox_CloseAll_Next:
	inc 1, iz
	cp iz, 0x10
	jr ule, GroupBox_CloseAll_Loop
	jr GroupBox_ReturnZero

	; --- Event 0x1C00036: Display Update ---
	; Enables display (FAA761 with WA=1), calls UpdateScreen, then disables.
GroupBox_DisplayUpdate:
	lds wa, 1
	call SetNeedUpdate
	call UpdateScreen
	lds wa, 0

GroupBox_DisableDisplay:
	call SetNeedUpdate

GroupBox_ReturnZero:
	lds32 xhl, 0
	jr GroupBox_Epilogue

GroupBox_ForwardToBoxProc:
	ld xde, (xsp + 30)
	ld xwa, (xsp + 38)
	ld xbc, (xsp + 34)
	calr BoxProc

GroupBox_Epilogue:
	popw iz
	lda xsp, (xsp + 40)
	ret

SetDialEnable:
	st16_24 0x03ef50, xwa
	ret

LABEL_F9A541:
	ld16_24 xhl, 0x03ef50
	ret

SetDialFocus:
	ld xde, xwa
	cpdm32_24 257898, xde
	ret z
	st32_24 0x03ef6a, xde
	ld xwa, 0xFFFFFFFF
	ld xbc, 0x1C0002C
	call SendEvent
	ret

GetDialFocus:
	cpdi16_24 257872, 0
	jr nz, LABEL_F9A573
	ld xhl, 0xFFFFFFFF
	ret

LABEL_F9A573:
	ld32_24 xhl, 0x03ef6a
	ret

SetDialUp:
	st32_24 0x03ef52, xwa
	st32_24 0x03ef5a, xbc
	st32_24 0x03ef62, xde
	jr SetDialFocus

SetDialDown:
	st32_24 0x03ef56, xwa
	st32_24 0x03ef5e, xbc
	st32_24 0x03ef66, xde
	jr SetDialFocus

SetAutoIncDefault:
	dec 4, xsp
	push xiz
	call GetRootObject
	ld xiz, xhl
	call GetRootEvent
	ld (xsp + 4), xhl
	call GetRootParam
	ld xde, xhl
	ld xwa, xiz
	ld xbc, (xsp + 4)
	calr SetAutoInc
	pop xiz
	inc 4, xsp
	ret

SetAutoInc:
	lda xsp, (xsp - 18)
	pushw iz
	ld (xsp + 8), xde
	ld (xsp + 12), xbc
	ld (xsp + 16), xwa
	call GetRootEvent
	cp xhl, 0x1C00026
	jr z, EventParam_FetchPoint
	cp xhl, 0x1C00009
	jr z, EventParam_FetchPoint
	cp xhl, 0x1C00007
	jr z, EventParam_FetchPoint
	cp xhl, 0x1C00008
	jrl nz, ApTimer_SetupReturn

EventParam_FetchPoint:
	call GetRootParam
	ld (xsp + 2), xhl
	ld xwa, (xsp + 2)
	cp xwa, 0xFF
	jrl ugt, ApTimer_SetupReturn
	ld xwa, (xsp + 2)
	and xwa, 0x1F
	ld (xsp + 6), wa
	ld xwa, (xsp + 2)
	srl xwa, 7
	and xwa, 0x1
	ld iz, wa
	extz xwa
	ld xbc, xwa
	sll xbc, 3
	sub xbc, xwa
	add xbc, xbc
	ld de, (xsp + 6)
	extz xde
	ld xwa, xde
	sll xwa, 3
	sub xwa, xde
	sll xwa, 2
	add xwa, xbc
	ld xbc, 0x274E8
	add xbc, xwa
	ld xwa, (xsp + 16)
	ld (xbc + 2), xwa
	ld xwa, (xsp + 12)
	ld (xbc + 6), xwa
	ld xwa, (xsp + 8)
	ld (xbc + 10), xwa
	cp (xbc + 1), 0x0
	jr nz, ApTimer_SetupReturn
	call GetRootObject
	ld xde, xhl
	ld wa, iz
	extz xwa
	ld xbc, xwa
	sll xbc, 3
	sub xbc, xwa
	add xbc, xbc
	ld wa, (xsp + 6)
	extz xwa
	ld xhl, xwa
	sll xhl, 3
	sub xhl, xwa
	sll xhl, 2
	add xhl, xbc
	lda_24 xwa, 0x0274e9
	add xwa, xhl
	ld (xwa), 0x1
	ld xwa, 0x1C00026
	push xwa
	ld xwa, (xsp + 6)
	push xwa
	ld xwa, 0x10
	ld xbc, xde
	call SetApTimer

ApTimer_SetupReturn:
	popw iz
	lda xsp, (xsp + 18)
	ret

ScreenProc:
	lda xsp, (xsp - 12)
	push xiz
	ld xiz, xde
	ld (xsp + 8), xbc
	ld (xsp + 12), xwa
	ld xwa, (xsp + 8)
	cp xwa, 0x1E0004A
	jrl z, Screen_GetDefault
	cp xwa, 0x1E00048
	jrl z, Screen_ReturnZero
	cp xwa, 0x1E0004B
	jrl z, Screen_GetStoredValue
	cp xwa, 0x1E00049
	jrl z, Screen_SetStoredValue
	cp xwa, 0x1C00007
	jrl z, Screen_OK
	cp xwa, 0x1C00009
	jrl z, Screen_Deactivate
	cp xwa, 0x1C0000D
	jrl z, Screen_Paint
	cp xwa, 0x1C00002
	jrl z, Screen_Close
	cp xwa, 0x1C00001
	jr z, Screen_Init
	ld xwa, (xsp + 12)
	ld xbc, (xsp + 8)
	ld xde, xiz
	jrl Screen_ForwardToGroupBox

Screen_Init_RegisterChild:
	ld xwa, xhl
	call SetCurrentTarget

Screen_Init:
	call GetCurrentTarget
	ld xwa, xhl
	ld xbc, 0x1E0004B
	lds32 xde, 0
	call SendEvent
	cp xhl, 0xFFFFFFFF
	jr nz, Screen_Init_RegisterChild
	call GetCurrentTarget
	ld xwa, xhl
	ld xbc, 0x1E00014
	ld xde, 0x1600033
	call SendEvent
	or xhl, xhl
	jr nz, Screen_Init_Setup

Screen_Init_CloseDeadChildren:
	ld xwa, 0xFFFFFFFF
	ld xbc, 0x1C00002
	ld xde, xiz
	call SendEvent
	call GetCurrentTarget
	ld xwa, xhl
	ld xbc, 0x1E00014
	ld xde, 0x1600033
	call SendEvent
	or xhl, xhl
	jr z, Screen_Init_CloseDeadChildren

Screen_Init_Setup:
	ld xwa, 0xFFFFFFFF
	ld xbc, 0x1C00002
	ld xde, xiz
	call SendEvent
	ld xwa, (xsp + 12)
	call GetViewInstance
	ld (xsp + 4), xhl
	cp xiz, 0x4
	jr z, Screen_Init_SetWall
	cp xiz, 0x3
	jr z, Screen_Init_ClearStoredValue
	cp xiz, 0x5
	jr z, Screen_Init_ClearStoredValue
	or xiz, xiz
	jr nz, Screen_Init_SetWall

Screen_Init_ClearStoredValue:
	ld xwa, (xsp + 4)
	ld xbc, (xwa + 30)
	ld xwa, 0xFFFFFFFF
	ld (xbc), xwa

Screen_Init_SetWall:
	calr PostTitle_Function
	cps hl, 0
	call_24 nz, 0xF9883C
	ld xwa, (xsp + 12)
	ld xbc, 0x1E000B1
	lds32 xde, 0
	call SendEvent
	ld wa, hl
	calr SetWallPaper
	ld xwa, (xsp + 12)
	ld xbc, 0x1E000B2
	lds32 xde, 0
	call SendEvent
	ld wa, hl
	calr SetWallColor
	calr PostTitle_Function
	cps hl, 0
	call_24 nz, 0xF9884B
	call GetTitleNow
	ld xwa, xhl
	ld xde, (xsp + 12)
	ld xbc, 0x1E00077
	call SendEvent
	ld xwa, (xsp + 12)
	ld xbc, (xsp + 8)
	ld xde, xiz
	calr GroupBoxProc
	cp xiz, 0x4
	jr nz, Screen_ReturnZero
	ld xwa, (xsp + 4)
	ld xbc, (xwa + 30)
	ld xwa, (xbc)
	cp xwa, 0xFFFFFFFF
	jr z, Screen_ReturnZero
	ld xwa, (xbc)
	ld xbc, (xsp + 8)
	ld xde, xiz
	call SendEvent

Screen_ReturnZero:
	lds32 xhl, 0
	jrl Screen_Return

Screen_Close:
	ld xwa, (xsp + 12)
	ld xbc, (xsp + 8)
	ld xde, xiz
	calr GroupBoxProc
	ld xwa, (xsp + 12)
	call GetViewInstance
	cp xiz, 0x3
	jr z, Screen_ReturnZero
	cp xiz, 0x4
	jr z, Screen_Close_ClearValue
	cp xiz, 0x5
	jr z, Screen_Close_ClearValue
	or xiz, xiz
	jr nz, Screen_ReturnZero

Screen_Close_ClearValue:
	ld xbc, (xhl + 30)
	ld xwa, 0xFFFFFFFF
	ld (xbc), xwa
	jr Screen_ReturnZero

Screen_Paint:
	call DrawWall
	jr Screen_ReturnZero

Screen_Deactivate:
	ld xwa, (xsp + 12)
	ld xbc, (xsp + 8)
	ld xde, xiz
	calr GroupBoxProc
	lds wa, 1
	call SetNeedUpdate
	call UpdateScreen
	lds wa, 0
	call SetNeedUpdate
	jr Screen_ReturnZero

Screen_OK:
	ld xwa, (xsp + 12)
	call GetViewInstance
	ld (xsp + 4), xhl
	ld xwa, (xsp + 12)
	ld xbc, 0x1E00024
	ld xde, 0x1600047
	call SendEvent
	or xhl, xhl
	jr nz, Screen_OK_Forward
	cp xiz, 0xF
	jr nz, Screen_OK_Forward
	call GetTitleNow
	ld xwa, xhl
	ld xbc, 0x1E0007A
	lds32 xde, 0
	call SendEvent
	or xhl, xhl
	jr nz, Screen_OK_NavUp
	ld xwa, (xsp + 4)
	ld xde, (xwa + 26)
	cp xde, 0x1A00000
	jr z, Screen_OK_Forward
	ld xwa, 0xFFFFFFFF
	ld xbc, 0x1C00015
	jr LABEL_F9A8FB

Screen_OK_NavUp:
	call GetTitleNow
	ld xwa, xhl
	ld xbc, 0x1E00079
	lds32 xde, 0
	call SendEvent
	call GetTitleNow
	ld xwa, xhl
	ld xbc, 0x1E0009A
	lds32 xde, 0

LABEL_F9A8FB:
	call SendEvent

Screen_OK_Forward:
	ld xwa, (xsp + 12)
	ld xbc, (xsp + 8)
	ld xde, xiz

Screen_ForwardToGroupBox:
	calr GroupBoxProc
	jr Screen_Return

Screen_SetStoredValue:
	ld xwa, (xsp + 12)
	call GetViewInstance
	ld xbc, (xhl + 30)
	ld (xbc), xiz
	jrl Screen_ReturnZero

Screen_GetStoredValue:
	ld xwa, (xsp + 12)
	call GetViewInstance
	ld xwa, (xhl + 30)
	ld xhl, (xwa)
	jr Screen_Return

Screen_GetDefault:
	ld xhl, 0xFFFFFFFF

Screen_Return:
	pop xiz
	lda xsp, (xsp + 12)
	ret

GetEditSwPoint:
	ld hl, wa
	lda xde, (xbc + 2)
	cp wa, 0x8C
	jr z, EditSwParam_Mode4
	cp wa, 0x8B
	jr z, EditSwParam_Mode3
	cp wa, 0x8A
	jr z, EditSwParam_Mode2
	cp wa, 0x89
	jr z, EditSwParam_Mode1
	cp wa, 0x88
	jr z, EditSwParam_Mode0
	cp hl, 0xC
	jrl ugt, EditSwParam_Default
	add hl, hl
	lda_24 xix, 0xea9b1c
	ld_sriw3 HL, 0x07, 0xF0, 0xEC
	lda_24 xix, 0xf9a973
	jp_dri 8, 0x07, 0xF0, 0xEC

; GetEditSwPoint handler: mode 0 (value=0x2B)
EditSwParam_Mode0:	; F9A973
	lds wa, 0
	jr LABEL_F9A97A
	ldw wa, 0x13F

LABEL_F9A97A:
	ld (xbc), wa
	ldw (xde), 0x2B
	ret

; GetEditSwPoint handler: mode 1 (value=0x55)
EditSwParam_Mode1:	; F9A981
	lds wa, 0
	jr LABEL_F9A988
	ldw wa, 0x13F

LABEL_F9A988:
	ld (xbc), wa
	ldw (xde), 0x55
	ret

; GetEditSwPoint handler: mode 2 (value=0x7F)
EditSwParam_Mode2:	; F9A98F
	lds wa, 0
	jr LABEL_F9A996
	ldw wa, 0x13F

LABEL_F9A996:
	ld (xbc), wa
	ldw (xde), 0x7F
	ret

; GetEditSwPoint handler: mode 3 (value=0xA9)
EditSwParam_Mode3:	; F9A99D
	lds wa, 0
	jr EditSwParam_Mode3_Store
	ldw wa, 0x13F

; GetEditSwPoint: store mode 3 result
EditSwParam_Mode3_Store:	; F9A9A4
	ld (xbc), wa
	ldw (xde), 0xA9
	ret

; GetEditSwPoint handler: mode 4 (value=0xD3)
EditSwParam_Mode4:	; F9A9AB
