; =============================================================================
; SoundParam_NotifyChange -- Notify UI of sound parameter change
; =============================================================================
; Hashes parameter ID and triggers UI refresh for affected widgets.
; Called after preset loads: 0x4002 for reverb, 0x4006 for EQ.
; Args: xwa = parameter ID
SoundParam_NotifyChange:
	lda xsp, (xsp - 10)
	push xiz
	ld (xsp + 10), de
	ld (xsp + 12), bc
	ldw (xsp + 4), 0x0
	ld xiz, xwa
	lds32 xwa, 0
	ld (xsp + 6), xwa
	ld xhl, xiz
	and xhl, 0xFF
	ld xwa, xhl
	sll xwa, 9
	add xwa, xhl
	ld xhl, xiz
	srl xhl, 8
	and xhl, 0xFF
	add xhl, xwa
	ld xwa, xhl
	sll xwa, 9
	add xwa, xhl
	ld xhl, xiz
	srl xhl, 0
	and xhl, 0x1F
	add xhl, xwa
	ld xwa, xhl
	ld xbc, 0x7FF
	call DivMod32
	ld ix, hl
	jr SndParam_ProbeEntry

	.include "sndparam_routines.s"

; MIDI Serial Communication routines (SC0)
	.include "midi_serial_routines.s"
	.include "midi_voice_routing.s"
	.include "dsp_config_sysex.s"
	.include "note_voice_mapping.s"

